<?php require_once __DIR__.'/_init.php'; $job=(int)($_GET['job']??0); $file=basename((string)($_GET['file']??'')); $st=$pdo->prepare('SELECT id FROM print_job_pages WHERE print_job_id=? AND preview_filename=?'); $st->execute([$job,$file]); if(!$st->fetch()){http_response_code(404);exit;} $path=pa_storage_root().'/jobs/'.$job.'/'.$file; if(!is_file($path)){http_response_code(404);exit;} header('Content-Type: image/png'); header('Content-Length: '.filesize($path)); header('Cache-Control: private,max-age=3600'); readfile($path);